/* @lc app=leetcode id=2916 lang=kotlin */
class Solution { fun sumCounts(nums: IntArray): Int = LongArray(4 * nums.size + 4).let { seg -> LongArray(4 * nums.size + 4).let { segsq -> LongArray(4 * nums.size + 4).let { lazy -> Array<((Int, Int, Int, Int, Int) -> Unit)?>(1) { null }.also { box -> box[0] = { node, l, r, ql, qr -> if (ql <= l && r <= qr) (r - l + 1).toLong().let { len -> segsq[node].let { segsq[node] = (it + 2 * seg[node] + len) % 1000000007L }.also { seg[node] = (seg[node] + len) % 1000000007L }.also { lazy[node] = (lazy[node] + 1) % 1000000007L } } else lazy[node].takeIf { it != 0L }?.let { v -> ((l + r) / 2).let { mid -> (mid - l + 1).toLong().let { lenL -> (r - mid).toLong().let { lenR -> (2 * node).let { lc -> (2 * node + 1).let { rc -> segsq[lc].let { segsq[lc] = (it + 2 * v * seg[lc] + lenL * (v * v % 1000000007L)) % 1000000007L }.also { seg[lc] = (seg[lc] + lenL * v) % 1000000007L }.also { lazy[lc] = (lazy[lc] + v) % 1000000007L }.also { segsq[rc] = (segsq[rc] + 2 * v * seg[rc] + lenR * (v * v % 1000000007L)) % 1000000007L }.also { seg[rc] = (seg[rc] + lenR * v) % 1000000007L }.also { lazy[rc] = (lazy[rc] + v) % 1000000007L }.also { lazy[node] = 0L } } } } } } }.run { ((l + r) / 2).let { mid -> (if (ql <= mid) box[0]!!(2 * node, l, mid, ql, qr) else Unit).also { if (qr > mid) box[0]!!(2 * node + 1, mid + 1, r, ql, qr) } } }.also { seg[node] = (seg[2 * node] + seg[2 * node + 1]) % 1000000007L }.also { segsq[node] = (segsq[2 * node] + segsq[2 * node + 1]) % 1000000007L } } }.let { box -> HashMap<Int, Int>().let { last -> nums.indices.fold(0L) { total, i -> last.getOrDefault(nums[i], -1).let { prev -> box[0]!!(1, 0, nums.size - 1, prev + 1, i) }.also { last[nums[i]] = i }.let { (total + segsq[1]) % 1000000007L } }.toInt() } } } } }